from pathlib import Path
p=Path('outputs/Everyday Personal Dashboard.html')
s=p.read_text()
def rep(a,b,label):
 global s
 if a not in s: raise SystemExit('missing anchor: '+label)
 s=s.replace(a,b,1)
# Dark cyber aesthetic across all existing components.
rep('</style>',r'''/* Neon after-dark interface */
:root{--bg:#070b14;--paper:#101827;--ink:#e9f4ff;--muted:#92a5ba;--line:#243247;--green:#78f0d3;--green2:#102c32;--orange:#ffbe6b;--lav:#251b42;--shadow:0 14px 42px #0007;--radius:18px}
body{color:var(--ink);background:radial-gradient(ellipse at 70% -14%,#183b4a 0,transparent 35%),radial-gradient(ellipse at 5% 45%,#19133a 0,transparent 32%),#070b14;background-attachment:fixed}
.side{background:linear-gradient(180deg,#0b1220ed,#0b1020f5);border-color:#263a50;box-shadow:12px 0 45px #0003;backdrop-filter:blur(18px)}.brand b{color:#e8f8ff}.mark{background:linear-gradient(145deg,#70e8d1,#956cff);box-shadow:0 0 24px #54e6db55;color:#071119}.navlabel{color:#71849c}.nav button{color:#a9b9ca}.nav button:hover,.nav button.active{background:linear-gradient(100deg,#15313a,#171d32);color:#8fffe3;box-shadow:inset 3px 0 #72f3dc,0 0 20px #35e4ce12}.nav .ico{color:#80e8d7}.sidefoot{color:#647890}.eyebrow{color:#70e8d1}.title{color:#f2f8ff;text-shadow:0 0 24px #a384ff26}.subtitle{color:#9aacc0}.card,.journal-entry,.saved-look,.garment{background:linear-gradient(145deg,#111b2b,#0d1522);border-color:#27374c;box-shadow:0 12px 38px #0003}.card:hover,.garment:hover,.journal-entry:hover{border-color:#3b6671;box-shadow:0 12px 35px #00e7ce13}.statlabel,.statnote,.muted,.sectionintro p{color:#91a3b7}.statval{color:#f4fbff;text-shadow:0 0 18px #72f0d533}.btn{background:#111d2d;border-color:#2d4056;color:#e1f2ff}.btn:hover{border-color:#67ddcf;color:#8cf9df;box-shadow:0 0 17px #63edcf19}.btn.primary{background:linear-gradient(110deg,#26bfae,#5e74ed);border:0;color:#04131a;box-shadow:0 0 25px #34d8c933;font-weight:750}.btn.soft{background:#102f34;color:#87f5dc;border-color:#23535a}.quick button{background:#101b2b;border-color:#283b50;color:#eaf7ff}.quick button:hover{background:#142d36;border-color:#63dccd;box-shadow:0 0 22px #39e8d51a}.pill{background:#1b293a;color:#b8c8da;border:1px solid #2b3d54}.pill.green{background:#102e32;color:#7af0d5;border-color:#205653}.pill.orange{background:#392b1e;color:#ffd18c;border-color:#6a4c26}.field,select,textarea{background:#0b1422;border-color:#2a3b51;color:#e7f4ff}.field::placeholder,textarea::placeholder{color:#697f95}.field:focus,select:focus,textarea:focus{outline:2px solid #50d9cb;border-color:transparent;box-shadow:0 0 22px #32deca20}.tablewrap{background:#0e1725;border-color:#2a3a4f}th{background:#131f30;color:#8ca5bc;border-color:#2a3a4f}td{border-color:#202f42;color:#dceafa}tr:hover td{background:#142132}.rowname{color:#eff9ff}.smallbtn{color:#90a6bb}.smallbtn:hover{background:#34202d;color:#ff89b7}.empty{color:#8397ac}.notice{background:linear-gradient(100deg,#102a34,#151a34);border-color:#284c59;color:#9cf4e2}.progress{background:#263449}.progress i{background:linear-gradient(90deg,#59e5ce,#9b78ff)}.modal{background:#020611c9;backdrop-filter:blur(9px)}.modalbox{background:linear-gradient(145deg,#142033,#0c1422);border:1px solid #344b66;color:#edf8ff;box-shadow:0 25px 90px #0009}.formfield{color:#adbed0}.checkline{border-color:#26374b}.checkline.done span{color:#647b91}.routine{border-color:#26374b}.routine strong{color:#7bf1d8}.journal-entry,.saved-look{color:#e7f4ff}.journal-date,.journal-sub,.wordcount{color:#8fa5bb}.journal-body{color:#c1d1e1}.journal-prompts button{background:#0d1928;color:#afc3d7;border-color:#2a3d53}.journal-prompts button:hover{background:#123039;color:#8af5dd}.garment-photo,.outfit-thumb,.saved-thumbs span,.outfit-piece img{background:linear-gradient(145deg,#192839,#202044);color:#8eeede}.garment-title,.outfit-name{color:#ebf8ff}.garment-meta,.outfit-sub{color:#8da4b9}.photo-btn,.favorite{background:#0b1422e8;color:#82f1da;border:1px solid #385466}.favorite.on{color:#ff7bb1}.pick-btn{background:#102a31;color:#81f3dc;border-color:#275b5b}.pick-btn.on{background:linear-gradient(110deg,#2acbb6,#697af4);color:#07131c;border:0}.toast{background:#122c34;border:1px solid #4bd8c5;color:#c9fff4;box-shadow:0 0 28px #30dccc2a}.journal-side .journal-stat{border-color:#283a4f}.outfit-piece{border-color:#293a50;background:#0c1625}.outfit-rail{background:linear-gradient(145deg,#142231,#17182c)}.edit-mode-only{display:none}.edit-mode .edit-mode-only{display:inline-flex}.edit-mode table th:last-child,.edit-mode .edit-mode-indicator{color:#83f3dc}.edit-toggle.active{background:#241a36;color:#d2a4ff;border-color:#9f78ff;box-shadow:0 0 17px #9e75ff2c}.fade-in{animation:fadein .28s ease both}@keyframes fadein{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
select option{background:#101827;color:#e9f4ff}button:disabled{opacity:.4;cursor:not-allowed}.outfit-piece img{object-fit:cover}.journal-modal textarea{color:#e5f2ff}
@media(max-width:900px){.side{background:#080e19f5;border-top-color:#2c465b}.nav button{color:#91a7ba}.nav button.active{box-shadow:inset 0 2px #70f0d8}.main{padding-bottom:100px}}
</style>''','neon theme')
# Edit mode button in header
rep('<button class="btn exportLabel" onclick="exportBackup()">Export backup</button>', '<button id="editToggle" class="btn edit-toggle" onclick="toggleEditMode()">✎ Edit mode: off</button><button class="btn exportLabel" onclick="exportBackup()">Export backup</button>', 'edit button')
rep("let page='home', searchTerm='',filter='All';", "let page='home', searchTerm='',filter='All',editMode=false;",'edit state')
# Replace render, make edit mode visual flag
rep("function render(){document.getElementById('pagetitle').textContent=navItems.find(n=>n[0]===page)?.[2]||'Overview';document.getElementById('pagesub').textContent=descriptions[page];document.getElementById('nav').innerHTML=navItems.map(n=>`<button class=\"${page===n[0]?'active':''}\" onclick=\"setPage('${n[0]}')\"><span class=\"ico\">${n[1]}</span>${n[2]}</button>`).join('');document.getElementById('view').innerHTML=({home:homeView,wardrobe:wardrobeView,outfits:outfitsView,journal:journalView,grooming:groomingView,care:careView,events:eventsView,watchlist:watchView,reading:readingView,tasks:tasksView,gym:gymView,weight:weightView}[page])();if(page==='wardrobe'||page==='outfits')hydratePhotos();}","function render(){document.getElementById('pagetitle').textContent=navItems.find(n=>n[0]===page)?.[2]||'Overview';document.getElementById('pagesub').textContent=descriptions[page];document.getElementById('nav').innerHTML=navItems.map(n=>`<button class=\"${page===n[0]?'active':''}\" onclick=\"setPage('${n[0]}')\"><span class=\"ico\">${n[1]}</span>${n[2]}</button>`).join('');let view=document.getElementById('view');view.innerHTML=({home:homeView,wardrobe:wardrobeView,outfits:outfitsView,journal:journalView,grooming:groomingView,care:careView,events:eventsView,watchlist:watchView,reading:readingView,tasks:tasksView,gym:gymView,weight:weightView}[page])();view.classList.toggle('edit-mode',editMode);let toggle=document.getElementById('editToggle');toggle.textContent=editMode?'✎ Edit mode: on':'✎ Edit mode: off';toggle.classList.toggle('active',editMode);if(page==='wardrobe'||page==='outfits')hydratePhotos();}", 'render edit mode')
rep("function setPage(p){page=p;searchTerm='';filter='All';render()}","function setPage(p){page=p;searchTerm='';filter='All';render()}\nfunction toggleEditMode(){editMode=!editMode;render();toast(editMode?'Edit controls are on':'Edit controls are off')}",'toggle function')
# Add edit button for wardrobe cards
rep("<button class=\"pick-btn ${state.selectedOutfit.includes(x.id)?'on':''}\" onclick=\"toggleOutfitItem('${x.id}')\">${state.selectedOutfit.includes(x.id)?'✓ Added':'＋ Outfit'}</button>","<button class=\"pick-btn ${state.selectedOutfit.includes(x.id)?'on':''}\" onclick=\"toggleOutfitItem('${x.id}')\">${state.selectedOutfit.includes(x.id)?'✓ Added':'＋ Outfit'}</button><button class=\"smallbtn edit-mode-only\" onclick=\"openForm('wardrobe','${x.id}')\">Edit</button>",'wardrobe edit button')
# Grooming edit button
rep("<td><button class=\"smallbtn\" onclick=\"removeItem('grooming','${x.id}')\">×</button></td></tr>","<td><button class=\"smallbtn edit-mode-only\" onclick=\"openForm('grooming','${x.id}')\">Edit</button><button class=\"smallbtn\" onclick=\"removeItem('grooming','${x.id}')\">×</button></td></tr>",'grooming edit')
# add edit button alongside each existing row's delete action
for typ in ['events','watchlist','reading','gym','weight']:
 old=f'<button class="smallbtn" onclick="removeItem(\'{typ}\',\'${{x.id}}\')">×</button>'
 new=f'<button class="smallbtn edit-mode-only" onclick="openForm(\'{typ}\',\'${{x.id}}\')">Edit</button><button class="smallbtn" onclick="removeItem(\'{typ}\',\'${{x.id}}\')">×</button>'
 rep(old,new,typ+' edit')
# Tasks get an edit control next to delete
rep("<button class=\"smallbtn\" onclick=\"event.preventDefault();removeItem('tasks','${x.id}')\">×</button>","<button class=\"smallbtn edit-mode-only\" onclick=\"event.preventDefault();openForm('tasks','${x.id}')\">Edit</button><button class=\"smallbtn\" onclick=\"event.preventDefault();removeItem('tasks','${x.id}')\">×</button>",'task edit')
# Ensure wardrobe form can edit category and status with deliberate pick lists
rep("wardrobe:{title:'Add a clothing item',fields:[['name','Item name','text','required'],['category','Category','text'],['colour','Colour / details','text'],['wash','Wash group','text'],['status','Laundry status','text']]}","wardrobe:{title:'Add a clothing item',fields:[['name','Item name','text','required'],['category','Category','text'],['colour','Colour / details','text'],['wash','Wash group','text'],['status','Laundry status','select','',['In Wardrobe','Clean','In Wash','To Put Away','Worn']] ]}",'wardrobe config')
# Replace form opener and submit handler to support edit prefill and preserve attached photos/favourites.
a=s.index('function openForm(type){')
b=s.index('function closeForm(){',a)
open_fn=r'''function openForm(type,id=''){let c=configs[type];if(!c)return;let item=id?state[type].find(x=>x.id===id):null;let values={};if(item){if(type==='wardrobe')values={name:item.Name,category:item.Category,colour:item['Colour / Details'],wash:item['Wash Category'],status:item['Laundry Status']};else if(type==='grooming')values={name:item.Name,category:item.Category,brand:item.Brand,routine:item.Routine,stock:item['Stock Level']};else values={...item}}let fields=c.fields.map(([key,label,t,req,opts])=>{let value=values[key]??'';return `<label class="formfield ${t==='textarea'?'full':''}"><span>${label}</span>${t==='select'?`<select name="${key}">${opts.map(o=>`<option value="${esc(o)}" ${String(value)===String(o)?'selected':''}>${esc(o)||'Not set'}</option>`).join('')}</select>`:t==='textarea'?`<textarea name="${key}" rows="3">${esc(value)}</textarea>`:`<input name="${key}" type="${t}" value="${esc(value)}" ${req==='required'?'required':''} ${t==='number'?'step="any"':''}>`}</label>`}).join('');document.getElementById('modalroot').innerHTML=`<div class="modal" onclick="if(event.target===this)closeForm()"><form class="modalbox" onsubmit="submitForm(event,'${type}')"><input type="hidden" name="editId" value="${esc(id)}"><div class="modalhead"><h2 style="margin:0">${item?'Edit':'Add'} ${c.title.replace(/^Add /,'')}</h2><button type="button" class="smallbtn" onclick="closeForm()">✕</button></div><div class="formgrid">${fields}</div><div class="modalactions"><button type="button" class="btn" onclick="closeForm()">Cancel</button><button class="btn primary">${item?'Save changes':'Save'}</button></div></form></div>`}
'''
s=s[:a]+open_fn+s[b:]
a=s.index('function submitForm(e,type){')
b=s.index('async function exportBackup(){',a)
submit=r'''function submitForm(e,type){e.preventDefault();let data=Object.fromEntries(new FormData(e.target).entries()),editId=data.editId;delete data.editId;let old=editId?state[type].find(x=>x.id===editId):null;let o={id:editId||type+Date.now(),...data};if(type==='wardrobe')o={...old,id:o.id,Name:o.name,Category:o.category,'Colour / Details':o.colour,'Wash Category':o.wash,'Laundry Status':o.status||'In Wardrobe',favorite:old?.favorite||false,photoKey:old?.photoKey};if(type==='grooming')o={...old,id:o.id,Name:o.name,Category:o.category,Brand:o.brand,Routine:o.routine,'Stock Level':o.stock};for(const k of ['episode','season','current','total','load','value'])if(o[k]!==undefined&&o[k]!=='')o[k]=Number(o[k]);if(type==='watchlist'){o.season=Number(o.season)||1;o.episode=Number(o.episode)||0}if(type==='reading'){o.current=Number(o.current)||0;o.total=Number(o.total)||0}if(type==='weight')o.value=Number(o.value);if(editId){let i=state[type].findIndex(x=>x.id===editId);if(i>=0)state[type][i]=o}else state[type].push(o);save();closeForm();toast(editId?'Entry updated':'Entry added');render()}
'''
s=s[:a]+submit+s[b:]
p.write_text(s)
print('Neon theme + edit mode applied',p.stat().st_size)
